export function install(t){Object.assign(t,{cardFrom:function(t){return t instanceof Element?t.closest(".link-card, .game-card, .music-track"):null},applyAccents:function(e=document){e.querySelectorAll(".link-card, .game-card").forEach(e=>{const n=`${e.getAttribute("href")||""} ${e.textContent||""}`,c=t.ACCENTS.find(([t])=>t.test(n));e.style.setProperty("--accent",c?c[1]:t.DEFAULT)})}})}